function watchMealDisplayTargetsFromAdjusted(
  adjusted: AdjustedDailyTarget | null | undefined,
): Partial<DailyNutritionPlan['targets']> | undefined {
  const macros = adjusted?.adjusted_macros;
  if (!adjusted || !macros) return undefined;
  return {
    calories: adjusted.adjusted_calories,
    protein: macros.protein_g,
    carbs: macros.carbs_g,
    fat: macros.fat_g,
  };
}

function hydrationRangeFields(targetOunces: number | null | undefined) {
  const range = hydrationTargetRangeOz(targetOunces ?? 64);
  return {
    target_ounces_min: range?.min,
    target_ounces_max: range?.max,
  };
}

function countLoggedWorkoutSets(rawSets: string | null | undefined): number {
  if (!rawSets) return 0;
  try {
    const parsed = JSON.parse(rawSets);
    if (!Array.isArray(parsed)) return 0;
    return parsed.reduce((total: number, entry: any) => {
      const sets = Array.isArray(entry?.sets) ? entry.sets.length : 0;
      return total + sets;
    }, 0);
  } catch {
    return 0;
  }
}

const ACTIVE_WORKOUT_TIMERS_KEY = 'activeWorkoutTimers';
const ACTIVE_WORKOUT_PAUSED_AT_KEY = 'activeWorkoutPausedAtMs';
const ACTIVE_WORKOUT_PAUSED_ACCUM_MS_KEY = 'activeWorkoutPausedAccumMs';

function hasActiveWorkoutTimers(rawTimers: string | null | undefined): boolean {
  if (!rawTimers) return false;
  try {
    const parsed = JSON.parse(rawTimers);
    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return false;
    return Object.values(parsed).some((timer: any) => timer?.running === true || Number(timer?.baseElapsed) > 0);
  } catch {
    return false;
  }
}

async function readWatchWorkoutActivityState(): Promise<WatchWorkoutActivityState> {
  let values: Record<string, string | null> = {};
  try {
    const pairs = await AsyncStorage.multiGet([
      'activeWorkoutStartTime',
      'activeWatchSessionId',
      'activeWorkoutSession',
      'activeWorkoutSets',
      ACTIVE_WORKOUT_TIMERS_KEY,
    ]);
    values = Object.fromEntries(pairs);
  } catch {
    return { isActive: false, sessionId: null };
  }

  const startedAt = parseInt(values.activeWorkoutStartTime ?? '', 10);
  if (!Number.isFinite(startedAt) || startedAt <= 0) {
    return { isActive: false, sessionId: null };
  }

  const ageMs = Date.now() - startedAt;
  if (ageMs >= 4 * 3600_000) {
    await AsyncStorage.multiRemove([
      'activeWorkoutStartTime',
      'activeWorkoutRest',
      ACTIVE_WORKOUT_TIMERS_KEY,
      'activeWatchSessionId',
      ACTIVE_WORKOUT_PAUSED_AT_KEY,
      ACTIVE_WORKOUT_PAUSED_ACCUM_MS_KEY,
    ]).catch(() => {});
    return { isActive: false, sessionId: null };
  }

  const hasPersistedWorkout = !!values.activeWorkoutSession?.trim();
  const loggedSets = countLoggedWorkoutSets(values.activeWorkoutSets);
  const hasTimers = hasActiveWorkoutTimers(values[ACTIVE_WORKOUT_TIMERS_KEY]);
  const inHandoffWindow = ageMs < WATCH_ACTIVE_HANDOFF_GRACE_MS;
  if (!hasPersistedWorkout && loggedSets <= 0 && !hasTimers && !inHandoffWindow) {
    await AsyncStorage.multiRemove([
      'activeWorkoutStartTime',
      'activeWorkoutRest',
      ACTIVE_WORKOUT_TIMERS_KEY,
      'activeWatchSessionId',
      ACTIVE_WORKOUT_PAUSED_AT_KEY,
      ACTIVE_WORKOUT_PAUSED_ACCUM_MS_KEY,
    ]).catch(() => {});
    return { isActive: false, sessionId: null };
  }

  const sessionId = values.activeWatchSessionId?.trim() || null;
  return { isActive: true, sessionId };
}

