type TodaySupplementMicroSnapshot = {
  ingredient_slug?: string | null;
  ingredient_name?: string | null;
  custom_name?: string | null;
  category?: string | null;
  description?: string | null;
  source_terms?: string[] | null;
  food_sources?: string[] | null;
  log_names?: string[] | null;
  dose_amount: number;
  dose_unit: string;
  taken_count: number;
  nutrient_content?: {
    serving_size?: { count?: number | null; unit?: string | null } | null;
    nutrients?: Array<{ key?: string; nutrient?: string; amount?: number; unit?: string }> | null;
  } | null;
};

function supplementMicroSnapshotsFromToday(supps: TodayStackItem[]): TodaySupplementMicroSnapshot[] {
  return supps.map(s => ({
    ingredient_slug: s.ingredient_slug ?? null,
    ingredient_name: s.ingredient_name ?? null,
    custom_name: s.custom_name ?? null,
    category: s.category ?? null,
    description: s.description ?? null,
    source_terms: s.source_terms ?? null,
    food_sources: s.food_sources ?? null,
    log_names: (s.logs_today ?? [])
      .filter(l => !l.skipped && l.name)
      .map(l => String(l.name)),
    dose_amount: s.dose_amount,
    dose_unit: s.dose_unit,
    taken_count: (s.logs_today ?? []).filter(l => !l.skipped).length,
    nutrient_content: s.nutrient_content ?? null,
  }));
}
