  const [editingCustomExercise, setEditingCustomExercise] = useState<CustomExerciseItem | null>(null);

  // Horizontal swipe → adjacent workout sub-tab.
  //
  // The actual gesture lives inside TabDragWrapper (see component);
  // this callback is what TabDragWrapper fires after a commit. We
  // route the navigation through here so the same side-effects that
  // run on tab-button taps (clear library detail, kick off history
  // bundle load) run on swipes too. Reused on the Library overlay,
  // which renders outside the main workout container.
  const workoutSubTabRef = useRef<'plan' | 'library' | 'equipment' | 'history'>('plan');
  useEffect(() => { workoutSubTabRef.current = workoutSubTab; }, [workoutSubTab]);
  const selectWorkoutSubTab = useCallback((next: 'plan' | 'library' | 'equipment' | 'history') => {
    workoutSubTabRef.current = next;
    // Drop any pending back-target whenever the user navigates between
    // sub-tabs — the ref is only meaningful while a detail view is open
    // on the same surface that opened it.
    exerciseBeforeEquipmentRef.current = null;
    if (next === 'plan') {
      setWorkoutSubTab('plan');
      setShowExerciseLibrary(false);
      setSelectedExercise(null);
      setSelectedEquipment(null);
    } else if (next === 'library') {
      setWorkoutSubTab('library');
      setSelectedExercise(null);
      setSelectedEquipment(null);
      setShowExerciseLibrary(true);
      ensureExerciseLibraryRef.current?.().catch(() => {});
    } else if (next === 'equipment') {
      setWorkoutSubTab('equipment');
      setShowExerciseLibrary(false);
      setSelectedExercise(null);
      setSelectedEquipment(null);
    } else {
      setWorkoutSubTab('history');
      setShowExerciseLibrary(false);
      setSelectedExercise(null);
      setSelectedEquipment(null);
      requestAnimationFrame(() => {
        loadWorkoutHistoryBundle().then(({ history, summaries }) => {
          setWorkoutHistoryList(history);
          setWorkoutHistorySummaries(summaries);
        }).catch(() => {});
      });
    }
  }, [loadWorkoutHistoryBundle]);
  const swipeWorkoutSubTab = useCallback((direction: -1 | 1) => {
    const idx = WORKOUT_SUBTAB_ORDER.indexOf(workoutSubTabRef.current);
    const next = WORKOUT_SUBTAB_ORDER[idx + direction];
    if (next) selectWorkoutSubTab(next);
  }, [selectWorkoutSubTab]);
  // Index of the current workout sub-tab. -1 if the state value isn't
  // in the visible order (defensive — shouldn't happen). Used by the
  // TabDragWrapper to know which directions are valid.
  const workoutSubTabIndex = WORKOUT_SUBTAB_ORDER.indexOf(workoutSubTab);



  // Meals sub-tab swipe — only visible segmented tabs participate.
