      <LiveActivityTracker
        visible={showLiveTracker}
        initialActivity={liveTrackerInitialActivity}
        finishSignal={liveTrackerFinishTick}
        onClose={() => {
          setShowLiveTracker(false);
          setLiveTrackerInitialActivity(null);
        }}
        themeName={userProfile.themePreference}
        enableHealthKit={!isFreeTier}
        authToken={authToken}
        onSave={async (session) => {
          await saveWorkoutSession(session);
          const sessionDate = dateKey(new Date(session.date));
          if (sessionDate === dateKey(new Date())) {
            import('../utils/workoutReminders')
              .then(({ cancelTodayWorkoutReminder }) => cancelTodayWorkoutReminder())
              .catch(() => undefined);
          }
          if (authToken) {
            try {
              await completeWorkoutWithOfflineQueue(
                authToken,
                {
                  workout_date: sessionDate,
                  focus_label: session.focus,
                  duration_seconds: session.durationSeconds,
                  activity: session.manualActivity ? {
                    category: session.manualActivity.category,
                    subtype: session.manualActivity.subtype,
                    intensity: session.manualActivity.intensity,
                    source: session.manualActivity.source,
                    cardioStyle: session.manualActivity.cardioStyle,
                    distanceMiles: session.manualActivity.distanceMiles,
                    caloriesBurned: session.manualActivity.caloriesBurned,
                    avgHeartRate: session.manualActivity.avgHeartRate,
                    details: session.manualActivity.details,
                    routeCoords: session.manualActivity.routeCoords,
                  } : undefined,
                  healthMetrics: appleHealthMetricsFromWorkoutSession(session),
                  source: {
                    sourceContext: session.manualActivity?.source === 'apple_health' ? 'apple_health' : undefined,
                    startedAt: session.startedAt ?? session.date,
                    endedAt: session.endedAt ?? null,
                    externalSourceId: session.id,
                  },
                },
                session,
              );
              await refreshNutritionAfterActivity(sessionDate);
            } catch {}
          }
        }}
        onSaved={() => {
          // Bump history so the streak / recent-sessions widgets pick
          // up the new row without needing a tab switch.
          (async () => {
            try {
              const { loadWorkoutHistory } = await import('../utils/workoutHistory');
              const fresh = await loadWorkoutHistory();
              setWorkoutHistoryList(fresh);
            } catch { /* non-fatal */ }
          })();
        }}
        onStartStrengthWorkout={(focus) => {
          // Strength pick from the Custom Workout sheet — mount the
          // existing ActiveWorkoutScreen on an empty workout shell with
          // the chosen focus. User adds their exercises inside, logs
          // sets normally, finishes through the standard summary path.
          // Same flow as plan-day Start but with no preloaded
          // exercises so the user is in full manual mode.
          const emptyDay: any = {
            day: new Date().toLocaleDateString('en-US', { weekday: 'long' }),
            focus,
            exercises: [],
            stimulus: 'mixed',
            _source_context: 'custom_strength',
          };
          void startCustomWorkoutForToday(emptyDay);
        }}
        onStartCardioWorkout={(label, subtype, category = 'cardio', cardioStyle, venue) => {
          // Timed custom pick → mount ActiveWorkoutScreen with a
          // synthetic activity WorkoutDay. ActiveWorkoutScreen handles:
          //   • Pushing the active session to the watch (HK + UI)
          //   • Starting expo-location's GPS tracker for distance/pace
          //   • Rendering the live route map + activity metrics row
          //   • Writing HKWorkoutRouteBuilder on finish
          // The focus label drives the watch-side `resolveActivity`
          // mapping → run / walk / cycling / etc. with .outdoor.
          const emptyDay: any = {
            day: new Date().toLocaleDateString('en-US', { weekday: 'long' }),
            focus: label,
            exercises: [],
            stimulus: category === 'mobility' ? 'mobility' : 'conditioning',
            _source_context: 'custom_cardio',
            _custom_activity_category: category,
            _custom_cardio_subtype: subtype,
            _custom_cardio_style: cardioStyle,
            ...(venue ? { _custom_activity_venue: venue } : {}),
          };
          void startCustomWorkoutForToday(emptyDay, { playCountdown: false });
        }}
      />

      <MealOverlayModals
